<?php namespace App\Http\Controllers; use App\Models\Rating; use Illuminate\Http\Request; class RatingController extends Controller { public function index(Request $r){$q=Rating::query(); if($r->filled('rateable_type')&&$r->filled('rateable_id'))$q->where('rateable_type',$r->rateable_type)->where('rateable_id',$r->rateable_id);return $q->with('user:id,name')->latest()->paginate(20);} public function store(Request $r){$d=$r->validate(['rateable_type'=>'required|in:App\Models\Vet,App\Models\Shelter,App\Models\Product','rateable_id'=>'required|integer','rating'=>'required|integer|min:1|max:5','comment'=>'nullable|string|max:2000']);return Rating::updateOrCreate(['user_id'=>$r->user()->id,'rateable_type'=>$d['rateable_type'],'rateable_id'=>$d['rateable_id']],['rating'=>$d['rating'],'comment'=>$d['comment']??null]);} }